let currentCategory = 'all';
let currentFilter = 'all';
let searchQuery = '';

document.addEventListener('DOMContentLoaded', () => {
  initSidebar();
  renderContent();
  initEventListeners();
});

function initSidebar() {
  const navContainer = document.getElementById('topicNav');
  navContainer.innerHTML = '';
  
  // All Topics option
  const allItem = document.createElement('div');
  allItem.className = 'nav-item active';
  allItem.innerHTML = `<span>All 18 Topics</span><span class="nav-count">150</span>`;
  allItem.onclick = () => selectCategory('all', allItem);
  navContainer.appendChild(allItem);
  
  Object.keys(NEETCODE_DATA).forEach(slug => {
    const chapter = NEETCODE_DATA[slug];
    const item = document.createElement('div');
    item.className = 'nav-item';
    item.innerHTML = `<span>${chapter.title}</span><span class="nav-count">${chapter.questions.length}</span>`;
    item.onclick = () => selectCategory(slug, item);
    navContainer.appendChild(item);
  });
}

function selectCategory(category, element) {
  currentCategory = category;
  document.querySelectorAll('.nav-item').forEach(el => el.classList.remove('active'));
  if (element) element.classList.add('active');
  renderContent();
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

function setFilter(difficulty, element) {
  currentFilter = difficulty;
  document.querySelectorAll('.filter-pill').forEach(el => el.classList.remove('active'));
  if (element) element.classList.add('active');
  renderContent();
}

function initEventListeners() {
  const searchInput = document.getElementById('searchInput');
  searchInput.addEventListener('input', (e) => {
    searchQuery = e.target.value.toLowerCase().trim();
    renderContent();
  });

  // Expand / Collapse All
  document.getElementById('expandAllBtn').addEventListener('click', () => {
    document.querySelectorAll('.hint-accordion, .solution-accordion').forEach(el => el.classList.add('open'));
  });

  document.getElementById('collapseAllBtn').addEventListener('click', () => {
    document.querySelectorAll('.hint-accordion, .solution-accordion').forEach(el => el.classList.remove('open'));
  });

  // Print button
  document.getElementById('printBtn').addEventListener('click', () => {
    // Automatically open all hints & solutions for print view
    document.querySelectorAll('.hint-accordion, .solution-accordion').forEach(el => el.classList.add('open'));
    window.print();
  });

  // Theme toggle
  document.getElementById('themeToggle').addEventListener('click', () => {
    const currentTheme = document.body.getAttribute('data-theme');
    const newTheme = currentTheme === 'light' ? 'dark' : 'light';
    document.body.setAttribute('data-theme', newTheme);
    document.getElementById('themeToggle').innerText = newTheme === 'light' ? '🌙 Dark' : '☀️ Light';
  });
}

function renderContent() {
  const container = document.getElementById('contentContainer');
  container.innerHTML = '';

  let chaptersToRender = [];
  if (currentCategory === 'all') {
    chaptersToRender = Object.keys(NEETCODE_DATA).map(slug => ({ slug, ...NEETCODE_DATA[slug] }));
  } else {
    chaptersToRender = [{ slug: currentCategory, ...NEETCODE_DATA[currentCategory] }];
  }

  let totalRendered = 0;

  chaptersToRender.forEach(chapter => {
    let matchingQuestions = chapter.questions.filter(q => {
      const matchFilter = (currentFilter === 'all' || q.difficulty.toLowerCase() === currentFilter.toLowerCase());
      const matchSearch = !searchQuery || (
        q.title.toLowerCase().includes(searchQuery) ||
        q.pattern.toLowerCase().includes(searchQuery) ||
        q.statement.toLowerCase().includes(searchQuery) ||
        String(q.id).includes(searchQuery)
      );
      return matchFilter && matchSearch;
    });

    if (matchingQuestions.length === 0) return;

    totalRendered += matchingQuestions.length;

    const chapterSection = document.createElement('section');
    chapterSection.className = 'chapter-section';
    chapterSection.innerHTML = `
      <div class="chapter-header">
        <h2 class="chapter-title">${chapter.title}</h2>
        <p class="chapter-desc">${chapter.description}</p>
      </div>
      <div class="questions-grid" id="grid-${chapter.slug}"></div>
    `;

    container.appendChild(chapterSection);
    const grid = chapterSection.querySelector(`#grid-${chapter.slug}`);

    matchingQuestions.forEach(q => {
      const card = createQuestionCard(q);
      grid.appendChild(card);
    });
  });

  if (totalRendered === 0) {
    container.innerHTML = `
      <div style="text-align: center; padding: 60px 20px; color: var(--text-muted);">
        <h3>No questions matched your search criteria</h3>
        <p style="margin-top: 8px;">Try adjusting your search query or difficulty filter.</p>
      </div>
    `;
  }
}

function createQuestionCard(q) {
  const card = document.createElement('div');
  card.className = 'question-card';
  card.id = `q-${q.id}`;

  const diffClass = q.difficulty.toLowerCase() === 'easy' ? 'badge-easy' : (q.difficulty.toLowerCase() === 'medium' ? 'badge-medium' : 'badge-hard');

  let examplesHtml = q.examples.map((ex, idx) => `
    <div class="example-item">
      <div><strong>Input:</strong> ${escapeHtml(ex.input)}</div>
      <div><strong>Output:</strong> ${escapeHtml(ex.output)}</div>
      ${ex.explanation ? `<div><strong>Explanation:</strong> ${escapeHtml(ex.explanation)}</div>` : ''}
    </div>
  `).join('');

  let hintsHtml = q.hints.map((hint, idx) => `
    <div class="hint-accordion">
      <button class="hint-toggle" onclick="toggleAccordion(this)">
        <span>💡 Hint ${idx + 1}</span>
        <span>▼</span>
      </button>
      <div class="hint-content">
        ${escapeHtml(hint)}
      </div>
    </div>
  `).join('');

  card.innerHTML = `
    <div class="card-header">
      <div class="card-title-group">
        <span class="q-id">#${q.id}</span>
        <h3 class="q-title">${escapeHtml(q.title)}</h3>
      </div>
      <div class="badges-group">
        <span class="badge ${diffClass}">${q.difficulty}</span>
        <span class="badge badge-pattern">${escapeHtml(q.pattern)}</span>
        <a href="${q.url}" target="_blank" class="badge" style="background: rgba(255,255,255,0.08); color: var(--text-secondary); text-decoration: none;">LeetCode ↗</a>
      </div>
    </div>

    <div>
      <div class="section-label">Problem Statement</div>
      <div class="statement-box">${escapeHtml(q.statement)}</div>
    </div>

    <div class="examples-box">
      ${examplesHtml}
    </div>

    <div class="analogy-box">
      <div class="analogy-title">🧠 Intuitive Mental Model / Analogy</div>
      <div>${escapeHtml(q.analogy)}</div>
    </div>

    <div class="hints-container">
      <div class="section-label">Step-by-Step Progressive Hints</div>
      ${hintsHtml}
    </div>

    <div class="solution-accordion">
      <button class="solution-toggle" onclick="toggleAccordion(this)">
        <span>✨ Canonical NeetCode Python 3 Solution & Walkthrough</span>
        <span>▼</span>
      </button>
      <div class="solution-content">
        <div class="walkthrough-box">
          <strong style="color: var(--text-primary); display: block; margin-bottom: 4px;">Walkthrough:</strong>
          ${escapeHtml(q.approach)}
        </div>
        <pre class="code-block"><code>${escapeHtml(q.solution)}</code></pre>
        <div class="complexity-bar">
          <div><strong>Time:</strong> ${escapeHtml(q.time_complexity)}</div>
          <div><strong>Space:</strong> ${escapeHtml(q.space_complexity)}</div>
        </div>
      </div>
    </div>
  `;

  return card;
}

function toggleAccordion(btn) {
  const parent = btn.parentElement;
  parent.classList.toggle('open');
  const arrow = btn.querySelector('span:last-child');
  if (arrow) {
    arrow.innerText = parent.classList.contains('open') ? '▲' : '▼';
  }
}

function escapeHtml(str) {
  if (!str) return '';
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}




