let currentModelMode = localStorage.getItem('neetcode_model_mode') || 'rag';
let geminiApiKey = localStorage.getItem('neetcode_gemini_api_key') || '';

document.addEventListener('DOMContentLoaded', () => {
  const modelSelect = document.getElementById('geminiModelSelect');
  if (modelSelect) modelSelect.value = currentModelMode;
  const keyInput = document.getElementById('geminiApiKeyInput');
  if (keyInput && geminiApiKey) keyInput.value = geminiApiKey;
  updateStatusBadge();
});

function toggleSettingsPanel() {
  const panel = document.getElementById('dockSettings');
  panel.style.display = panel.style.display === 'none' ? 'block' : 'none';
}

function saveApiKey() {
  const key = document.getElementById('geminiApiKeyInput').value.trim();
  geminiApiKey = key;
  localStorage.setItem('neetcode_gemini_api_key', key);
  if (key && currentModelMode === 'rag') {
    currentModelMode = 'gemini-2.0-flash';
    document.getElementById('geminiModelSelect').value = 'gemini-2.0-flash';
    localStorage.setItem('neetcode_model_mode', 'gemini-2.0-flash');
  }
  updateStatusBadge();
  toggleSettingsPanel();
  addAssistantMessage("Gemini API Key saved successfully! Active engine: " + (currentModelMode === 'rag' ? 'In-Memory RAG' : currentModelMode));
}

function changeModelMode(mode) {
  currentModelMode = mode;
  localStorage.setItem('neetcode_model_mode', mode);
  updateStatusBadge();
}

function updateStatusBadge() {
  const badge = document.getElementById('modelStatusBadge');
  if (!badge) return;
  if (currentModelMode === 'rag') {
    badge.innerText = 'Active RAG • 150 Problems';
    badge.style.color = '#60a5fa';
  } else if (geminiApiKey) {
    badge.innerText = currentModelMode.toUpperCase() + ' • Live AI';
    badge.style.color = '#34d399';
  } else {
    badge.innerText = 'API Key Needed • Offline';
    badge.style.color = '#f59e0b';
  }
}

// 1. One-Click Question Jump in Notes
function jumpToQuestion(qId) {
  let targetSlug = null;
  let targetQuestion = null;

  for (const slug of Object.keys(NEETCODE_DATA)) {
    const found = NEETCODE_DATA[slug].questions.find(q => String(q.id) === String(qId));
    if (found) {
      targetSlug = slug;
      targetQuestion = found;
      break;
    }
  }

  if (!targetQuestion) {
    console.warn("Question not found:", qId);
    return;
  }

  // If question is filtered out or in different category, switch to that category
  if (currentCategory !== 'all' && currentCategory !== targetSlug) {
    selectCategory(targetSlug);
  }
  if (currentFilter !== 'all' && currentFilter.toLowerCase() !== targetQuestion.difficulty.toLowerCase()) {
    currentFilter = 'all';
    document.querySelectorAll('.filter-pill').forEach(el => el.classList.remove('active'));
    document.querySelector('.filter-pill').classList.add('active');
    renderContent();
  }

  setTimeout(() => {
    const cardEl = document.getElementById(`q-${qId}`);
    if (cardEl) {
      cardEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
      cardEl.classList.remove('highlighted');
      void cardEl.offsetWidth; // Trigger reflow
      cardEl.classList.add('highlighted');

      // Expand hint & solution accordions
      cardEl.querySelectorAll('.hint-accordion, .solution-accordion').forEach(el => el.classList.add('open'));
    }
  }, 100);
}

// 2. Chat Quick Prompt
function askQuickPrompt(promptText) {
  const input = document.getElementById('chatInput');
  input.value = promptText;
  handleChatSubmit(new Event('submit'));
}

// 3. Search Engine over 150 NeetCode Problems
function searchNeetCodeData(query) {
  const qClean = query.toLowerCase().trim();
  const tokens = qClean.split(/\s+/).filter(t => t.length > 1);

  const results = [];

  for (const slug of Object.keys(NEETCODE_DATA)) {
    const chapter = NEETCODE_DATA[slug];
    for (const q of chapter.questions) {
      let score = 0;
      const titleLower = q.title.toLowerCase();
      const patternLower = q.pattern.toLowerCase();
      const diffLower = q.difficulty.toLowerCase();
      const statementLower = q.statement.toLowerCase();
      const idStr = String(q.id);

      if (titleLower === qClean) score += 100;
      else if (titleLower.includes(qClean)) score += 60;

      if (idStr === qClean || `#${idStr}` === qClean) score += 95;

      if (patternLower.includes(qClean)) score += 50;

      tokens.forEach(tok => {
        if (titleLower.includes(tok)) score += 20;
        if (patternLower.includes(tok)) score += 15;
        if (diffLower === tok) score += 10;
        if (statementLower.includes(tok)) score += 5;
      });

      if (score > 0) {
        results.push({ question: q, chapterTitle: chapter.title, score });
      }
    }
  }

  results.sort((a, b) => b.score - a.score);
  return results;
}

// 4. Main Chat Submission Handler
async function handleChatSubmit(event) {
  if (event) event.preventDefault();
  const input = document.getElementById('chatInput');
  const query = input.value.trim();
  if (!query) return;

  addUserMessage(query);
  input.value = '';

  // Case A: Live Gemini API Mode
  if (currentModelMode !== 'rag' && geminiApiKey) {
    await handleGeminiApiCall(query);
    return;
  }

  // Case B: Offline In-Memory RAG Mode
  handleOfflineRagCall(query);
}

function handleOfflineRagCall(query) {
  const matches = searchNeetCodeData(query);

  if (matches.length === 0) {
    addAssistantMessage(`
      I searched all 150 NeetCode problems, but couldn't find an exact match for <em>"${escapeHtml(query)}"</em>.
      <br><br>
      💡 <strong>Try searching for:</strong>
      <ul style="margin: 8px 0 0 18px;">
        <li>Problem name (e.g. <code>Trapping Rain Water</code>, <code>Two Sum</code>, <code>LRU Cache</code>)</li>
        <li>Pattern name (e.g. <code>Monotonic Stack</code>, <code>Sliding Window</code>, <code>Trie</code>, <code>Backtracking</code>)</li>
        <li>Difficulty + topic (e.g. <code>Hard DP</code>, <code>Binary Search</code>, <code>Two Pointers</code>)</li>
      </ul>
    `);
    return;
  }

  const top = matches[0].question;

  // Single exact problem or best match
  let responseHtml = `
    <div style="font-size: 0.95rem; font-weight: 700; color: #FFFFFF; margin-bottom: 4px;">
      #${top.id}: ${escapeHtml(top.title)}
    </div>
    <div style="display: flex; gap: 6px; margin-bottom: 8px;">
      <span class="badge ${top.difficulty.toLowerCase() === 'easy' ? 'badge-easy' : (top.difficulty.toLowerCase() === 'medium' ? 'badge-medium' : 'badge-hard')}">${top.difficulty}</span>
      <span class="badge badge-pattern">${escapeHtml(top.pattern)}</span>
    </div>
    <div style="font-size: 0.82rem; color: #CBD5E1; margin-bottom: 8px;">
      <strong>Intuitive Analogy:</strong> ${escapeHtml(top.analogy || top.approach)}
    </div>
    <div style="font-size: 0.78rem; font-family: var(--font-mono); color: #60A5FA; margin-bottom: 10px;">
      Time: ${escapeHtml(top.time_complexity || 'O(N)')} &bull; Space: ${escapeHtml(top.space_complexity || 'O(1)')}
    </div>
    <div class="chat-action-row">
      <button class="btn-jump" onclick="jumpToQuestion(${top.id})">📍 Jump to Problem in Notes</button>
      <a href="${top.url}" target="_blank" class="btn-leetcode">LeetCode ↗</a>
    </div>
  `;

  // If query matched multiple related problems (e.g. pattern search)
  if (matches.length > 1) {
    responseHtml += `
      <div style="margin-top: 14px; padding-top: 10px; border-top: 1px solid var(--bg-card-border);">
        <strong style="color: #60A5FA; font-size: 0.8rem;">Other matching problems:</strong>
        <div style="display: flex; flex-direction: column; gap: 6px; margin-top: 6px;">
    `;
    matches.slice(1, 5).forEach(m => {
      responseHtml += `
        <div style="display: flex; justify-content: space-between; align-items: center; background: rgba(0,0,0,0.2); padding: 4px 8px; border-radius: 6px;">
          <span style="font-size: 0.8rem; color: #E2E8F0;">#${m.question.id} ${escapeHtml(m.question.title)} (${m.question.difficulty})</span>
          <button class="btn-jump" style="padding: 2px 6px; font-size: 0.7rem;" onclick="jumpToQuestion(${m.question.id})">Jump</button>
        </div>
      `;
    });
    responseHtml += `</div></div>`;
  }

  addAssistantMessage(responseHtml);
}

async function handleGeminiApiCall(query) {
  const loadingId = 'loading-' + Date.now();
  addAssistantMessage('<span id="' + loadingId + '">Thinking with ' + currentModelMode + '...</span>');

  try {
    const matches = searchNeetCodeData(query).slice(0, 3);
    const groundings = matches.map(m => `Problem #${m.question.id} ${m.question.title} (${m.question.difficulty}): Pattern: ${m.question.pattern}, Statement: ${m.question.statement}, Solution: ${m.question.approach}`).join('\n');

    const systemPrompt = `You are a Senior DSA Placement Mentor and Algorithmic Coach for NeetCode 150.
Answer concisely with intuition, edge cases, time/space complexity, and clean Python code where relevant.
Relevant NeetCode Problems for context:
${groundings}`;

    const url = `https://generativelanguage.googleapis.com/v1beta/models/${currentModelMode}:streamGenerateContent?key=${geminiApiKey}`;

    const payload = {
      contents: [
        {
          role: "user",
          parts: [{ text: `${systemPrompt}\n\nStudent Question: ${query}` }]
        }
      ]
    };

    const res = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });

    const data = await res.json();
    const loadingEl = document.getElementById(loadingId);

    if (data.error) {
      if (loadingEl) loadingEl.parentElement.innerHTML = `⚠️ Gemini API Error: ${escapeHtml(data.error.message)}<br><small>Falling back to offline In-Memory RAG.</small>`;
      handleOfflineRagCall(query);
      return;
    }

    const answer = data.candidates?.[0]?.content?.parts?.[0]?.text || "No response received.";
    let formattedAnswer = escapeHtml(answer).replace(/\n/g, '<br>');

    if (matches.length > 0) {
      formattedAnswer += `
        <div class="chat-action-row" style="margin-top: 12px;">
          <button class="btn-jump" onclick="jumpToQuestion(${matches[0].question.id})">📍 Jump to #${matches[0].question.id} ${escapeHtml(matches[0].question.title)}</button>
        </div>
      `;
    }

    if (loadingEl) loadingEl.parentElement.innerHTML = formattedAnswer;

  } catch (err) {
    console.error("Gemini API call failed:", err);
    const loadingEl = document.getElementById(loadingId);
    if (loadingEl) loadingEl.parentElement.innerHTML = `⚠️ Network error calling Gemini. Falling back to offline RAG.<br>`;
    handleOfflineRagCall(query);
  }
}

function addUserMessage(text) {
  const container = document.getElementById('chatMessages');
  const bubble = document.createElement('div');
  bubble.className = 'chat-bubble user';
  bubble.innerText = text;
  container.appendChild(bubble);
  container.scrollTop = container.scrollHeight;
}

function addAssistantMessage(htmlContent) {
  const container = document.getElementById('chatMessages');
  const bubble = document.createElement('div');
  bubble.className = 'chat-bubble assistant';
  bubble.innerHTML = htmlContent;
  container.appendChild(bubble);
  container.scrollTop = container.scrollHeight;
}
